        {currentPage === Page.ADMIN && <AdminDashboard items={items} setItems={setItems} orders={[]} setOrders={()=>{}} reviews={[]} setReviews={()=>{}} onExit={() => setCurrentPage(Page.HOME)} />}
      </main>

      <Navbar currentPage={currentPage} setPage={setCurrentPage} cartCount={cart.length} />
      <AIChat />
      <ItemDetailsModal item={selectedItem} isOpen={!!selectedItem} onClose={() => setSelectedItem(null)} onAddToCart={handleAddToCart} />
      <UpsellModal isOpen={showUpsell} onClose={() => setShowUpsell(false)} suggestions={items.filter(i => i.category === 'Boisson' || i.category === 'Dessert').slice(0, 3)} onAdd={(i) => handleAddToCart(i, 1, '')} onProceed={handleCheckout} />
      {showReceipt && activeOrder && <Receipt order={activeOrder} onClose={() => setShowReceipt(false)} />}
    </div>
  );
};

export default App;

import { createClient } from '@supabase/supabase-js';

// Récupération des clés depuis l'environnement Vite
const supabaseUrl = import.meta.env.VITE_SUPABASE_URL || '';
const supabaseKey = import.meta.env.VITE_SUPABASE_ANON_KEY || '';

// Vérification de la configuration
const isValid = supabaseUrl.startsWith('https://') && supabaseKey.length > 20;

export const supabase = isValid ? createClient(supabaseUrl, supabaseKey) : null;

if (!isValid) {
  console.warn("⚠️ Configuration Supabase manquante ou invalide. L'application fonctionne en mode local.");
}

import React, { useState, useEffect, useMemo } from 'react';
import Navbar from './components/Navbar.tsx';
import AIChat from './components/AIChat.tsx';
import AdminDashboard from './components/AdminDashboard.tsx';
import DeliveryEstimator from './components/DeliveryEstimator.tsx';
