import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, ShoppingBag, Utensils, X, TrendingUp, RefreshCw
} from 'lucide-react';
import { MenuItem, AdminView, Order, OrderStatus } from '../types';
import { KhadyLogo } from './KhadyLogo';
import { supabase } from '../lib/supabase.ts';

interface AdminDashboardProps {
  items: MenuItem[];
  setItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
  reviews: any[];
  setReviews: any;
  onExit: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  items, onExit, setOrders, orders 
}) => {
  const [currentView, setCurrentView] = useState<AdminView>(AdminView.DASHBOARD);
  const [loading, setLoading] = useState(false);

  const fetchRealData = async () => {
    if (!supabase) return;
    setLoading(true);
    const { data: orderData } = await supabase.from('orders').select('*').order('timestamp', { ascending: false });
    if (orderData) {
      setOrders(orderData.map(o => ({
        id: o.id, customerName: o.customer_name, phone: o.phone, status: o.status as OrderStatus, total: o.total, timestamp: o.timestamp, items: o.items || []
      })));
    }
    setLoading(false);
  };

  useEffect(() => { fetchRealData(); }, []);

  const sidebarItems = [
    { view: AdminView.DASHBOARD, icon: LayoutDashboard, label: 'Bilan' },
    { view: AdminView.ORDERS, icon: ShoppingBag, label: 'Commandes' },
    { view: AdminView.MENU_MGMT, icon: Utensils, label: 'Plats' },
  ];

  const totalCA = orders.reduce((acc, o) => acc + o.total, 0);

  const renderSection = () => {
    switch(currentView) {
      case AdminView.DASHBOARD:
        return (
          <div className="space-y-8 animate-fade-in">
             <div className="grid grid-cols-2 gap-4">
                <div className="bg-white/5 p-8 rounded-[3.5rem] border border-white/5">
                   <div className="flex justify-between items-start mb-4 opacity-30"><TrendingUp size={24}/></div>
                   <p className="text-[10px] text-white/40 uppercase font-black mb-1">Chiffre d'Affaires</p>
                   <h4 className="text-2xl font-black italic">{totalCA.toLocaleString()} F</h4>
                </div>
                <div className="bg-white/5 p-8 rounded-[3.5rem] border border-white/5">
                   <div className="flex justify-between items-start mb-4 opacity-30"><ShoppingBag size={24}/></div>
                   <p className="text-[10px] text-white/40 uppercase font-black mb-1">Commandes</p>
                   <h4 className="text-2xl font-black italic">{orders.length}</h4>
                </div>
             </div>

             <div className="bg-brand-gold/10 p-8 rounded-[3rem] border border-brand-gold/20">
                <h3 className="text-brand-gold font-black text-xs uppercase italic mb-4">Actions Rapides</h3>
                <button onClick={fetchRealData} className="w-full bg-white/5 py-4 rounded-2xl flex items-center justify-center gap-2 text-[10px] font-black uppercase">
                  <RefreshCw size={14} className={loading ? "animate-spin" : ""}/> Actualiser les données
                </button>
             </div>
          </div>
        );

      case AdminView.MENU_MGMT:
        return (
          <div className="space-y-6 animate-fade-in">
            <h3 className="text-2xl font-black uppercase italic text-brand-gold">Ma Carte</h3>
            <div className="grid grid-cols-2 gap-4">
              {items.map(item => (
                <div key={item.id} className="bg-white/5 p-4 rounded-[2rem] border border-white/5">
                   <img src={item.image} className="w-full aspect-square object-cover rounded-xl mb-3" />
                   <p className="font-black text-[10px] uppercase truncate">{item.name}</p>
                   <p className="text-brand-gold font-black text-[9px]">{item.price} F</p>
                </div>
              ))}
            </div>
          </div>
        );

      case AdminView.ORDERS:
        return (
          <div className="space-y-6 animate-fade-in">
             <h3 className="text-2xl font-black uppercase italic text-brand-gold">Suivi Commandes</h3>
             <div className="space-y-4">
                {orders.length === 0 ? <p className="text-xs text-white/20 italic">Aucune commande pour le moment.</p> : 
                  orders.map(order => (
                    <div key={order.id} className="bg-white/5 p-6 rounded-[2.5rem] border border-white/5 flex justify-between items-center">
                       <div>
                          <p className="text-lg font-black italic">{order.id}</p>
                          <p className="text-[10px] font-bold text-white/40">{order.customerName}</p>
                       </div>
                       <span className="bg-brand-gold/20 text-brand-gold px-4 py-2 rounded-full text-[8px] font-black uppercase">{order.status}</span>
                    </div>
                  ))
                }
             </div>
          </div>
        );

      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-[#1A0F0D] flex flex-col text-white overflow-hidden">
      <div className="p-6 flex justify-between items-center border-b border-white/5 bg-[#1A0F0D]/95 backdrop-blur-lg">
         <KhadyLogo variant="light" className="scale-75" />
         <button onClick={onExit} className="p-4 bg-red-500/20 text-red-500 rounded-2xl"><X size={20} /></button>
      </div>
      <div className="flex flex-1 overflow-hidden">
        <div className="w-20 bg-white/5 border-r border-white/5 flex flex-col items-center py-6 gap-6">
          {sidebarItems.map(item => (
            <button key={item.view} onClick={() => setCurrentView(item.view)} className={`p-4 rounded-2xl transition-all ${currentView === item.view ? 'bg-brand-orange text-white' : 'text-white/30'}`}>
              <item.icon size={20} />
            </button>
          ))}
        </div>
        <div className="flex-1 overflow-y-auto p-8 no-scrollbar pb-32">{renderSection()}</div>
      </div>
    </div>
  );
};

export default AdminDashboard;

