import { GoogleGenAI } from "@google/genai";
import { MENU_ITEMS, BILLO_INFO } from "../constants";

export interface ChatMessage {
  role: 'user' | 'model';
  parts: { text: string }[];
}

/**
 * Khady IA - L'intelligence culinaire de Niamey
 */
export const getSmartResponse = async (userMessage: string, history: ChatMessage[] = []): Promise<string> => {
  const apiKey = process.env.API_KEY;

  if (!apiKey) {
    return "Salam ! Je prépare actuellement mes épices. Consultez notre menu en attendant ! 🥘 (Clé API manquante)";
  }

  try {
    const ai = new GoogleGenAI({ apiKey });

    const systemInstruction = `
      Tu es "Khady IA", l'ambassadrice digitale de "Khady's Food & Event" à Niamey.
      TON TON : Très chaleureux, poli, luxueux et typiquement nigérien (utilise "Salam", "Barka", "Fofo", "C'est le goût !").

      MENU ACTUEL : ${MENU_ITEMS.map(i => `${i.name} (${i.price} F)`).join(', ')}.

      MISSIONS :
      1. Recommander des plats selon les envies.
      2. Toujours suggérer un accompagnement (Bissap, Dégué).
      3. Préciser que la livraison est assurée par ${BILLO_INFO.name} (1000F à 2500F).
      4. Pour les mariages, rediriger vers la section "Event".

      CONSIGNE : Max 3 phrases. Sois passionnée par la cuisine africaine.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [...history, { role: 'user', parts: [{ text: userMessage }] }],
      config: {
        systemInstruction,
        temperature: 0.8,
      },
    });

    return response.text || "Barka ! Je n'ai pas bien saisi, pouvez-vous reformuler ?";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Fofo ! Une petite perturbation réseau, mais je reste à votre service pour vos commandes !";
  }
};

