import UpsellModal from './components/UpsellModal.tsx';
import OrderTracking from './components/OrderTracking.tsx';
import Receipt from './components/Receipt.tsx';
import Toast, { ToastType } from './components/Toast.tsx';
import { KhadyLogo } from './components/KhadyLogo.tsx';
import { playSound } from './utils/audio.ts';
import { Page, MenuItem, CartItem, Order, MenuCategory } from './types.ts';
import { MENU_ITEMS, LOGO_VIDEO_URL } from './constants.ts';
import { supabase } from './lib/supabase.ts'; // Import centralisé corrigé
import { 
  User, Trophy, Package, Calendar, SkipForward, ArrowLeft, UtensilsCrossed, Heart, Download, Search, Sparkles, TrendingUp
} from 'lucide-react';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [splashFade, setSplashFade] = useState(false);
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [toast, setToast] = useState<{message: string, type: ToastType} | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState<MenuCategory | 'Tous'>('Tous');

  const [cart, setCart] = useState<CartItem[]>(() => {
    const saved = localStorage.getItem('khadys_cart');
    return saved ? JSON.parse(saved) : [];
  });

  const [items, setItems] = useState<MenuItem[]>(MENU_ITEMS);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [showReceipt, setShowReceipt] = useState(false);
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null);
  const [showUpsell, setShowUpsell] = useState(false);
  const [heroIdx, setHeroIdx] = useState(0);

  const categories: (MenuCategory | 'Tous')[] = ['Tous', 'Plat Africain', 'Box Sauce', 'Plat Européen', 'Pack', 'Boisson', 'Dessert'];

  useEffect(() => {
    const fetchMenu = async () => {
      if (!supabase) return;
      try {
        const { data, error } = await supabase
          .from('menu_items')
          .select('*')
          .eq('is_available', true);

        if (error) throw error;

        if (data && data.length > 0) {
          const mappedData: MenuItem[] = data.map((item: any) => ({
            id: item.id,
            name: item.name,
            description: item.description,
            price: item.price,
            image: item.image,
            category: item.category as MenuCategory,
            rating: item.rating,
            isAvailable: item.is_available,
            isSpicy: item.is_spicy,
            isVegetarian: item.is_vegetarian,
            isPlatDuJour: item.is_plat_du_jour,
            isSpécialitéMaison: item.is_specialite_maison,
            isPromo: item.is_promo,
            includes: item.includes,
            minPeople: item.min_people
          }));
          setItems(mappedData);
        }
      } catch (e) {
        console.error("Erreur chargement menu:", e);
      }
    };
    fetchMenu();
  }, []);

  useEffect(() => {
    const timer = setInterval(() => {
      const specials = items.filter(i => i.isSpécialitéMaison);
      if (specials.length > 0) {
        setHeroIdx(p => (p + 1) % specials.length);
      }
    }, 7000);
    return () => clearInterval(timer);
  }, [items]);

  useEffect(() => {
    localStorage.setItem('khadys_cart', JSON.stringify(cart));
  }, [cart]);

  const showNotification = (message: string, type: ToastType = 'success') => setToast({ message, type });

  const handleAddToCart = (item: MenuItem, quantity: number, instructions: string) => {
    const existing = cart.find(c => c.id === item.id);
    if (existing) {
      setCart(cart.map(c => c.id === item.id ? { ...c, quantity: c.quantity + quantity, instructions } : c));
    } else {
      setCart([...cart, { ...item, quantity, instructions }]);
    }
    playSound('pop');
    showNotification(`${item.name} ajouté !`);
  };

  const handleCheckout = async () => {
    const total = cart.reduce((acc, i) => acc + (i.price * i.quantity), 0);
    const orderId = `KH-${Math.floor(1000 + Math.random() * 9000)}`;

    const newOrder: Order = {
      id: orderId,
      customerName: "Client Niamey",
      phone: "N/A",
      address: "Niamey",
      district: "Plateau",
      items: [...cart],
      total,
      deliveryFee: 1000,
      status: 'RECEIVED',
      paymentMethod: 'CASH',
      timestamp: new Date().toISOString()
    };

    try {
      if (supabase) {
        const { error } = await supabase.from('orders').insert([{ 
          id: orderId, 
          total, 
          status: 'RECEIVED',
          customer_name: newOrder.customerName,
          phone: newOrder.phone,
          items: cart
        }]);
        if (error) throw error;
      }

      setActiveOrder(newOrder);
      setCart([]);
      setShowUpsell(false);
      playSound('cash');
      setCurrentPage(Page.COMMANDES);
      showNotification("Commande reçue !");
    } catch (e) {
      console.error("Erreur checkout:", e);
      showNotification("Erreur lors de la commande", "error");
    }
  };

  const filteredItems = useMemo(() => {
    let result = items;
    if (currentPage === Page.BOX) result = items.filter(i => i.category.includes('Box'));
    else if (currentPage === Page.PACKS) result = items.filter(i => i.category === 'Pack' || i.category === 'Buffet');
    else if (activeCategory !== 'Tous') result = items.filter(i => i.category === activeCategory);

    if (searchQuery) {
      result = result.filter(i => i.name.toLowerCase().includes(searchQuery.toLowerCase()) || i.description.toLowerCase().includes(searchQuery.toLowerCase()));
    }
    return result;
  }, [items, currentPage, activeCategory, searchQuery]);

  if (showSplash) {
    return (
      <div className={`fixed inset-0 z-[100] bg-black flex items-center justify-center transition-opacity duration-1000 ${splashFade ? 'opacity-0' : 'opacity-100'}`}>
        <video autoPlay muted playsInline className="w-full h-full object-cover" onEnded={() => {setSplashFade(true); setTimeout(()=>setShowSplash(false), 800);}}>
          <source src={LOGO_VIDEO_URL} type="video/mp4" />
        </video>
        <button onClick={() => setShowSplash(false)} className="absolute bottom-10 right-6 bg-white/20 backdrop-blur-md text-white px-6 py-3 rounded-full text-[10px] font-black uppercase tracking-widest">Passer</button>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-brand-light flex flex-col items-center selection:bg-brand-orange selection:text-white">
      {toast && <Toast {...toast} onClose={() => setToast(null)} />}

      <main className="flex-1 w-full max-w-lg bg-brand-light min-h-screen pb-32">
        {currentPage === Page.HOME && (
          <div className="animate-fade-in">
            <header className="flex justify-between items-center p-6 bg-white/80 backdrop-blur-md sticky top-0 z-40 border-b border-brand-brown/5">
              <KhadyLogo />
              <div className="flex gap-2">
                <button onClick={() => setCurrentPage(Page.COMMANDES)} className="w-11 h-11 rounded-2xl bg-brand-orange/10 text-brand-orange flex items-center justify-center border border-brand-orange/10">
                  <TrendingUp size={18} />
                </button>
                <button onClick={() => setCurrentPage(Page.COMPTE)} className="w-11 h-11 rounded-2xl bg-brand-brown/5 flex items-center justify-center border border-brand-brown/10">
                  <User size={18} className="text-brand-brown/60" />
                </button>
              </div>
            </header>

            <div className="bg-brand-brown py-2 overflow-hidden whitespace-nowrap relative marquee-container">
              <div className="inline-block animate-marquee">
                {[...Array(3)].map((_, i) => (
                  <span key={i} className="text-[10px] font-black text-brand-gold uppercase tracking-[0.2em] italic mx-4">
                    ✨ Promo du Jour : -10% sur les Box Sauces ! 🥘 Livraison Express avec Billo ! 🛵 Jummua'h Mubarak à tous ! 🕌
                  </span>
                ))}
              </div>
            </div>

            <section className="px-6 mt-6">
              <div className="relative aspect-[16/10] rounded-[2.5rem] overflow-hidden shadow-2xl bg-brand-brown group">
                <img src={items.filter(i => i.isSpécialitéMaison)[heroIdx]?.image || items[0].image} className="w-full h-full object-cover opacity-80 group-hover:scale-105 transition-transform duration-1000" alt="Hero" />
                <div className="absolute inset-0 bg-gradient-to-t from-brand-brown via-transparent to-transparent opacity-60"></div>
                <div className="absolute bottom-8 left-8 text-white">
                  <div className="flex items-center gap-2 mb-2">
                    <span className="bg-brand-orange px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-widest">Spécialité</span>
                  </div>
                  <h3 className="text-3xl font-black italic uppercase leading-none tracking-tighter">{items.filter(i => i.isSpécialitéMaison)[heroIdx]?.name || "Tiep Premium"}</h3>
                  <p className="text-brand-gold text-[10px] font-black uppercase tracking-[0.3em] mt-2">L'excellence au Plateau</p>
                </div>
              </div>
            </section>

            <nav className="grid grid-cols-2 gap-4 px-6 mt-8">
              <button onClick={() => setCurrentPage(Page.MENU)} className="bg-brand-brown h-44 rounded-[3rem] text-brand-gold flex flex-col items-center justify-center gap-4 shadow-xl active:scale-95 transition-transform border-4 border-white/5">
                <div className="w-16 h-16 rounded-full bg-brand-gold/10 flex items-center justify-center"><UtensilsCrossed size={36} /></div>
                <span className="font-black text-[11px] uppercase italic tracking-[0.2em]">La Carte Royale</span>
              </button>
              <div className="grid grid-rows-2 gap-4">
                <button onClick={() => setCurrentPage(Page.BOX)} className="bg-brand-orange text-white rounded-[2.5rem] flex items-center justify-center gap-3 font-black text-[10px] uppercase italic shadow-lg active:scale-95 border-4 border-white/5">
                  <Package size={20} /> Box Sauce
                </button>
                <button onClick={() => setCurrentPage(Page.TRAITEUR)} className="bg-brand-gold text-brand-brown rounded-[2.5rem] flex items-center justify-center gap-3 font-black text-[10px] uppercase italic shadow-lg active:scale-95 border-4 border-white/5">
                  <Calendar size={20} /> Event
                </button>
              </div>
            </nav>

            <section className="px-6 mt-12 mb-8">
              <div className="flex justify-between items-end mb-6">
                <h4 className="font-black text-brand-brown uppercase italic flex items-center gap-2"><Heart className="text-brand-orange fill-brand-orange" size={18}/> Coups de Cœur</h4>
                <button onClick={() => setCurrentPage(Page.MENU)} className="text-[9px] font-black uppercase text-brand-orange border-b-2 border-brand-orange">Voir tout</button>
              </div>
              <div className="flex gap-4 overflow-x-auto no-scrollbar pb-4">
                {items.filter(i => i.rating === 5).slice(0, 4).map(item => (
                  <div key={item.id} onClick={() => setSelectedItem(item)} className="min-w-[160px] bg-white rounded-[2.2rem] p-3 shadow-sm border border-gray-100">
                    <img src={item.image} className="w-full aspect-square object-cover rounded-[1.8rem] mb-3" />
                    <p className="font-black text-[9px] uppercase truncate px-1">{item.name}</p>
                    <p className="text-brand-orange font-black text-[10px] mt-1 px-1">{item.price} F</p>
                  </div>
                ))}
              </div>
            </section>

            <div className="px-6 mb-12">
               <DeliveryEstimator />
            </div>
          </div>
        )}

        {(currentPage === Page.MENU || currentPage === Page.BOX || currentPage === Page.PACKS) && (
          <div className="animate-fade-in flex flex-col min-h-screen">
            <header className="sticky top-0 z-40 bg-brand-light/90 backdrop-blur-xl p-6 border-b border-brand-brown/5">
              <div className="flex items-center gap-4 mb-6">
                <button onClick={() => setCurrentPage(Page.HOME)} className="p-3 bg-white rounded-2xl shadow-sm text-brand-brown"><ArrowLeft size={20}/></button>
                <h2 className="text-xl font-black italic uppercase tracking-tighter">
                  {currentPage === Page.BOX ? "Nos Box Sauces" : currentPage === Page.PACKS ? "Traiteur & Packs" : "Le Menu Khady's"}
                </h2>
              </div>

              <div className="relative mb-6">
                <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-brand-brown/30" />
                <input 
                  type="text" 
                  placeholder="Rechercher un plat..." 
                  className="w-full bg-white border-none rounded-2xl py-4 pl-14 pr-6 text-xs font-bold shadow-sm focus:ring-2 focus:ring-brand-orange/20"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>

              {currentPage === Page.MENU && (
                <div className="flex gap-2 overflow-x-auto no-scrollbar py-2">
                  {categories.map(cat => (
                    <button 
                      key={cat} 
                      onClick={() => setActiveCategory(cat)}
                      className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase whitespace-nowrap transition-all border ${activeCategory === cat ? 'bg-brand-brown text-brand-gold border-brand-brown shadow-lg' : 'bg-white text-brand-brown/40 border-gray-100'}`}
                    >
                      {cat}
                    </button>
                  ))}
                </div>
              )}
            </header>

            <div className="p-6 grid grid-cols-2 gap-5">
              {filteredItems.length > 0 ? filteredItems.map(item => (
                <div key={item.id} onClick={() => setSelectedItem(item)} className="bg-white rounded-[2.5rem] overflow-hidden shadow-sm border border-gray-50 flex flex-col animate-slide-up">
                  <div className="relative aspect-square">
                    <img src={item.image} className="w-full h-full object-cover" />
                    {item.isSpécialitéMaison && <span className="absolute top-3 left-3 bg-brand-orange text-white text-[7px] font-black uppercase px-2 py-1 rounded-full shadow-lg">Chef</span>}
                  </div>
                  <div className="p-5 flex-1 flex flex-col justify-between">
                    <div>
                      <p className="font-black text-[10px] uppercase truncate mb-1 leading-tight">{item.name}</p>
                      <p className="text-gray-400 text-[8px] font-bold line-clamp-2 italic leading-relaxed">{item.description}</p>
                    </div>
                    <div className="flex items-center justify-between mt-4">
                      <p className="text-brand-brown font-black text-[12px] italic">{item.price} F</p>
                      <div className="w-8 h-8 rounded-xl bg-brand-orange/10 text-brand-orange flex items-center justify-center"><Sparkles size={14}/></div>
                    </div>
                  </div>
                </div>
              )) : (
                <div className="col-span-2 py-20 text-center">
                  <p className="text-gray-300 font-black italic uppercase text-xs">Aucun plat trouvé 🍲</p>
                </div>
              )}
            </div>
          </div>
        )}

        {currentPage === Page.TRAITEUR && <TraiteurView />}
        {currentPage === Page.CART && (
           <div className="p-6 animate-fade-in">
             <div className="flex items-center gap-4 mb-10">
                <button onClick={() => setCurrentPage(Page.HOME)} className="p-3 bg-white rounded-2xl shadow-sm"><ArrowLeft size={20}/></button>
                <h2 className="text-2xl font-black italic uppercase tracking-tighter">Mon Panier</h2>
             </div>

             {cart.length === 0 ? (
               <div className="flex flex-col items-center justify-center py-20 text-gray-300">
                  <div className="w-24 h-24 bg-gray-100 rounded-full flex items-center justify-center mb-6 opacity-50"><Package size={40} /></div>
                  <p className="font-black italic uppercase text-xs">Le panier attend vos choix...</p>
                  <button onClick={() => setCurrentPage(Page.MENU)} className="mt-8 bg-brand-orange text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase italic shadow-lg">Découvrir le menu</button>
               </div>
             ) : (
               <div className="space-y-4">
                 {cart.map(item => (
                   <div key={item.id} className="flex items-center gap-5 bg-white p-5 rounded-[2.2rem] shadow-sm border border-gray-50">
                     <img src={item.image} className="w-20 h-20 rounded-2xl object-cover shadow-sm" />
                     <div className="flex-1 min-w-0">
                        <p className="font-black text-[11px] uppercase truncate">{item.name}</p>
                        <p className="text-[10px] text-gray-400 font-bold mb-2">Quantité: {item.quantity}</p>
                        <p className="text-brand-orange font-black text-[11px] italic">{(item.price * item.quantity).toLocaleString()} F</p>
                     </div>
                     <button onClick={() => setCart(cart.filter(c => c.id !== item.id))} className="text-red-300 hover:text-red-500 p-2"><Download size={16} className="rotate-45" /></button>
                   </div>
                 ))}

                 <div className="mt-12 p-10 bg-brand-brown text-brand-gold rounded-[3.5rem] shadow-2xl relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-brand-orange/5 rounded-full -mr-16 -mt-16"></div>
                    <div className="flex justify-between items-center mb-8">
                       <span className="font-black uppercase text-[10px] tracking-widest opacity-60">Total de votre festin</span>
                       <span className="text-3xl font-black italic tracking-tighter">{cart.reduce((a, b) => a + (b.price * b.quantity), 0).toLocaleString()} F</span>
                    </div>
                    <button onClick={() => setShowUpsell(true)} className="w-full bg-brand-orange text-white py-6 rounded-[2rem] font-black uppercase text-xs shadow-xl italic tracking-[0.1em] active:scale-95 transition-transform">Valider la commande</button>
                 </div>
               </div>
             )}
           </div>
        )}

        {currentPage === Page.COMMANDES && (
           <div className="p-6 animate-fade-in">
             <div className="flex items-center gap-4 mb-10">
                <button onClick={() => setCurrentPage(Page.HOME)} className="p-3 bg-white rounded-2xl shadow-sm"><ArrowLeft size={20}/></button>
                <h2 className="text-2xl font-black italic uppercase tracking-tighter">Suivi Livraison</h2>
             </div>
             {activeOrder ? <OrderTracking order={activeOrder} onComplete={() => setShowReceipt(true)} /> : (
               <div className="py-20 flex flex-col items-center justify-center opacity-30 italic font-black">
                  <div className="w-20 h-20 bg-gray-200 rounded-full flex items-center justify-center mb-6"><SkipForward size={32} /></div>
                  <p className="text-xs uppercase">Aucune commande active</p>
               </div>
             )}
           </div>
        )}

        {currentPage === Page.COMPTE && (
          <div className="p-10 flex flex-col items-center animate-fade-in">
            <header className="w-full flex justify-between items-center mb-10">
               <button onClick={() => setCurrentPage(Page.HOME)} className="p-3 bg-white rounded-2xl shadow-sm"><ArrowLeft size={20}/></button>
               <h2 className="text-lg font-black italic uppercase">Mon Profil</h2>
               <div className="w-10"></div>
            </header>

            <div className="w-40 h-40 rounded-full bg-brand-brown border-8 border-white shadow-2xl flex items-center justify-center text-brand-gold mb-8 relative">
              <User size={80} strokeWidth={1.5} />
              <div className="absolute -bottom-2 right-2 bg-brand-orange text-white p-3 rounded-2xl shadow-lg border-4 border-white"><Trophy size={20}/></div>
            </div>

            <h3 className="text-2xl font-black uppercase italic tracking-tighter text-brand-brown">Client Privilège</h3>
            <p className="text-[10px] font-black text-brand-orange uppercase tracking-[0.3em] mt-2 italic">Club Khady Niamey</p>

            <div className="w-full mt-12 space-y-5">
              <div className="bg-white p-8 rounded-[2.5rem] flex items-center justify-between shadow-sm border border-gray-50 group hover:shadow-md transition-shadow">
                <div>
                   <span className="text-[10px] font-black uppercase text-gray-400 tracking-widest block mb-1">Points Fidélité</span>
                   <span className="text-2xl font-black text-brand-brown italic">1,250 PTS</span>
                </div>
                <div className="w-14 h-14 rounded-2xl bg-brand-gold/10 text-brand-gold flex items-center justify-center group-hover:scale-110 transition-transform"><Sparkles size={28}/></div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                 <button className="bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100 flex flex-col items-center gap-2">
                    <Package size={20} className="text-brand-brown/40" />
                    <span className="text-[8px] font-black uppercase tracking-widest">Historique</span>
                 </button>
                 <button className="bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100 flex flex-col items-center gap-2">
                    <Download size={20} className="text-brand-brown/40" />
                    <span className="text-[8px] font-black uppercase tracking-widest">Factures</span>
                 </button>
              </div>

              <button onClick={() => { if(prompt("Pass?")==='khadysfood') setCurrentPage(Page.ADMIN) }} className="w-full py-6 text-gray-300 flex items-center justify-center opacity-40 mt-10 hover:opacity-100 transition-opacity">
                 <span className="text-[9px] font-black uppercase tracking-[0.4em]">Administration</span>
              </button>
            </div>
          </div>
        )}

        {currentPage === Page.ADMIN && <AdminDashboard items={items} setItems={setItems} orders={[]} setOrders={()=>{}} reviews={[]} setReviews={()=>{}} onExit={() => setCurrentPage(Page.HOME)} />}
      </main>

      <Navbar currentPage={currentPage} setPage={setCurrentPage} cartCount={cart.length} />
      <AIChat />
      <ItemDetailsModal item={selectedItem} isOpen={!!selectedItem} onClose={() => setSelectedItem(null)} onAddToCart={handleAddToCart} />
      <UpsellModal isOpen={showUpsell} onClose={() => setShowUpsell(false)} suggestions={items.filter(i => i.category === 'Boisson' || i.category === 'Dessert').slice(0, 3)} onAdd={(i) => handleAddToCart(i, 1, '')} onProceed={handleCheckout} />
      {showReceipt && activeOrder && <Receipt order={activeOrder} onClose={() => setShowReceipt(false)} />}
    </div>
  );
};

export default App;

export type MenuCategory = 
  | 'Entree' 
  | 'Plat Africain' 
  | 'Plat Européen' 
  | 'Spécialité Maison' 
  | 'Plat du Jour' 
  | 'Dessert' 
  | 'Boisson' 
  | 'Box Sauce'
  | 'Box Repas'
  | 'Pack'
  | 'Buffet'
  | 'Pack-Buffet';

export type OrderStatus = 
  | 'RECEIVED' 
  | 'CONFIRMED' 
  | 'PREPARING' 
  | 'READY' 
  | 'DELIVERING' 
  | 'DELIVERED'
  | 'CANCELLED';

export type PaymentMethod = 
  | 'CASH' 
  | 'AIRTEL_MONEY' 
  | 'MOOV_MONEY' 
  | 'NITA' 
  | 'MYNITA' 
  | 'AMANATA' 
  | 'ALLIZA' 
  | 'ZEYNA' 
  | 'CARD';

export interface MenuItem {
  id: string;
  name: string;
  description: string;
  price: number;
  image: string;
  category: MenuCategory;
  rating: number;
  isAvailable: boolean;
  isSpicy?: boolean;
  isVegetarian?: boolean;
  isPlatDuJour?: boolean;
  isSpécialitéMaison?: boolean;
  isPromo?: boolean;
  includes?: string[]; 
  minPeople?: number;  
}

export interface Review {
  id: string;
  name: string;
  comment: string;
  rating: number;
  image: string;
  date: string;
  adminReply?: string; 
}

export interface CartItem extends MenuItem {
  quantity: number;
  instructions?: string;
}

export interface Order {
  id: string;
  customerName: string;
  phone: string;
  address: string;
  district: string;
  items: CartItem[];
  total: number;
  deliveryFee: number;
  status: OrderStatus;
  paymentMethod: PaymentMethod;
  timestamp: string;
}

export interface UserProfile {
  name: string;
  phone: string;
  points: number;
  rank: 'Silver' | 'Gold' | 'Platinum';
  avatar?: string;
  referralCode: string;
}

export enum Page {
  HOME = 'HOME',
  MENU = 'MENU',
  TRAITEUR = 'TRAITEUR',
  CART = 'CART',
  BOX = 'BOX',
  PACKS = 'PACKS',
  COMMANDES = 'COMMANDES',
  COMPTE = 'COMPTE',
  INFOS = 'INFOS',
  ADMIN = 'ADMIN'
}

export enum AdminView {
  DASHBOARD = 'DASHBOARD',
  ORDERS = 'ORDERS',
  MENU_MGMT = 'MENU_MGMT',
  REVIEWS = 'REVIEWS',
  BOX_SAUCES = 'BOX_SAUCES',
  PACK_BUFFET = 'PACK_BUFFET',
  CATERING = 'CATERING',
