import { supabase } from '../lib/supabase.ts';
import { playSound } from '../utils/audio';

interface AdminDashboardProps {
  items: MenuItem[];
  setItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
  reviews: Review[];
  setReviews: React.Dispatch<React.SetStateAction<Review[]>>;
  onExit: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  items, onExit, setOrders, orders, reviews, setReviews 
}) => {
  const [currentView, setCurrentView] = useState<AdminView>(AdminView.DASHBOARD);
  const [loading, setLoading] = useState(false);
  const [replyingTo, setReplyingTo] = useState<string | null>(null);
  const [replyText, setReplyText] = useState('');
  const [adminProfile, setAdminProfile] = useState({ name: 'Khady Admin', avatar: undefined as string | undefined });

  const fetchRealData = async () => {
    if (!supabase) return;
    setLoading(true);
    const { data: orderData } = await supabase.from('orders').select('*').order('timestamp', { ascending: false });
    if (orderData) {
      setOrders(orderData.map(o => ({
        id: o.id, customerName: o.customer_name, phone: o.phone, status: o.status as OrderStatus, total: o.total, timestamp: o.timestamp, items: o.items || []
      })));
    }
    setLoading(false);
  };

  useEffect(() => { fetchRealData(); }, []);

  const handleReply = (id: string) => {
    setReviews(prev => prev.map(r => r.id === id ? { ...r, adminReply: replyText } : r));
    setReplyingTo(null);
    setReplyText('');
    playSound('success');
  };

  const sidebarItems = [
    { view: AdminView.DASHBOARD, icon: LayoutDashboard, label: 'Bilan' },
    { view: AdminView.ORDERS, icon: ShoppingBag, label: 'Commandes' },
    { view: AdminView.MENU_MGMT, icon: Utensils, label: 'Plats' },
    { view: AdminView.REVIEWS, icon: MessageCircle, label: 'Avis' },
  ];

  const totalCA = orders.reduce((acc, o) => acc + o.total, 0);

  const renderSection = () => {
    switch(currentView) {
      case AdminView.DASHBOARD:
        return (
          <div className="space-y-8 animate-fade-in">
             <div className="grid grid-cols-2 gap-4">
                <div className="bg-white/5 p-8 rounded-[3.5rem] border border-white/5">
