                </div>
                <div className="bg-white/5 p-8 rounded-[3.5rem] border border-white/5">
                   <p className="text-[10px] text-white/40 uppercase font-black mb-1">Commandes</p>
                   <h4 className="text-2xl font-black italic">{orders.length}</h4>
                </div>
             </div>

             <div className="bg-brand-brown p-10 rounded-[3rem] border border-white/5 flex items-center gap-6">
                <div className="relative group">
                  <div className="w-24 h-24 rounded-full bg-brand-gold/10 border-4 border-white/10 flex items-center justify-center overflow-hidden">
                    {adminProfile.avatar ? <img src={adminProfile.avatar} className="w-full h-full object-cover" /> : <User size={40} className="text-brand-gold" />}
                  </div>
                  <label className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 cursor-pointer rounded-full">
                     <Camera size={20} className="text-white" />
                     <input type="file" className="hidden" accept="image/*" onChange={(e) => {
                       const file = e.target.files?.[0];
                       if(file) {
                         const reader = new FileReader();
                         reader.onloadend = () => setAdminProfile({...adminProfile, avatar: reader.result as string});
                         reader.readAsDataURL(file);
                       }
                     }} />
                  </label>
                </div>
                <div>
                  <h3 className="text-xl font-black uppercase italic text-brand-gold">{adminProfile.name}</h3>
                  <p className="text-[10px] text-white/40 font-black uppercase tracking-widest mt-1">Super Admin Khady's</p>
                </div>
             </div>
          </div>
        );

      case AdminView.REVIEWS:
        return (
          <div className="space-y-6 animate-fade-in">
             <h3 className="text-2xl font-black uppercase italic text-brand-gold">Avis Clients</h3>
             <div className="space-y-4">
                {reviews.map(rev => (
                  <div key={rev.id} className="bg-white/5 p-6 rounded-[2.5rem] border border-white/5">
                     <div className="flex items-center gap-4 mb-4">
                        <img src={rev.image} className="w-10 h-10 rounded-full object-cover" />
                        <div>
                           <p className="font-black text-xs uppercase italic">{rev.name}</p>
                           <div className="flex gap-1 text-brand-gold"><Star size={8} fill="currentColor" /> <Star size={8} fill="currentColor" /> <Star size={8} fill="currentColor" /></div>
                        </div>
                     </div>
                     <p className="text-xs text-white/60 italic mb-4">"{rev.comment}"</p>

                     {rev.adminReply ? (
                        <div className="bg-brand-gold/10 p-4 rounded-2xl border-l-4 border-brand-gold">
                           <p className="text-[8px] font-black text-brand-gold uppercase mb-1">Votre réponse</p>
                           <p className="text-[10px] text-white/80">{rev.adminReply}</p>
                        </div>
                     ) : replyingTo === rev.id ? (
                        <div className="mt-4 flex gap-2">
                           <input type="text" autoFocus className="flex-1 bg-white/5 border-0 rounded-xl p-3 text-[10px] text-white" placeholder="Votre réponse..." value={replyText} onChange={e => setReplyText(e.target.value)} />
                           <button onClick={() => handleReply(rev.id)} className="p-3 bg-brand-gold text-brand-brown rounded-xl"><Send size={16}/></button>
                        </div>
                     ) : (
                        <button onClick={() => setReplyingTo(rev.id)} className="text-[9px] font-black uppercase text-brand-gold underline decoration-brand-gold/30">Répondre</button>
                     )}
