        );

      case AdminView.ORDERS:
        return (
          <div className="space-y-6 animate-fade-in">
             <h3 className="text-2xl font-black uppercase italic text-brand-gold">Suivi Livraison</h3>
             <div className="space-y-4">
                {orders.map(order => (
                  <div key={order.id} className="bg-white/5 p-6 rounded-[2.5rem] border border-white/5 flex justify-between items-center">
                     <div>
                        <p className="text-lg font-black italic">{order.id}</p>
                        <p className="text-[10px] font-bold text-white/40">{order.customerName}</p>
                        <p className="text-[8px] font-black text-brand-gold uppercase mt-1">{order.paymentMethod}</p>
                     </div>
                     <span className="bg-brand-gold/20 text-brand-gold px-4 py-2 rounded-full text-[8px] font-black uppercase">{order.status}</span>
                  </div>
                ))}
             </div>
          </div>
        );

      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-[#1A0F0D] flex flex-col text-white overflow-hidden">
      <div className="p-6 flex justify-between items-center border-b border-white/5 bg-[#1A0F0D]/95 backdrop-blur-lg">
         <KhadyLogo variant="light" className="scale-75" />
         <button onClick={onExit} className="p-4 bg-red-500/20 text-red-500 rounded-2xl"><X size={20} /></button>
      </div>
      <div className="flex flex-1 overflow-hidden">
        <div className="w-20 bg-white/5 border-r border-white/5 flex flex-col items-center py-6 gap-6">
          {sidebarItems.map(item => (
            <button key={item.view} onClick={() => setCurrentView(item.view)} className={`p-4 rounded-2xl transition-all ${currentView === item.view ? 'bg-brand-orange text-white' : 'text-white/30'}`}>
