import React, { useState, useEffect } from 'react';
import { Order, OrderStatus } from '../types';
import { playSound } from '../utils/audio';
import { Clock, CheckCircle2, ChefHat, Bike, PackageCheck, Box, Bell, MapPin, Navigation } from 'lucide-react';

interface OrderTrackingProps {
  order: Order;
  onComplete: () => void;
}

const Smile = () => <div className="text-xl animate-bounce">🤩</div>;

const steps: { status: OrderStatus; label: string; icon: any; sound: any }[] = [
  { status: 'RECEIVED', label: 'Reçu', icon: Box, sound: 'pop' },
  { status: 'CONFIRMED', label: 'Confirmé', icon: CheckCircle2, sound: 'notification' },
  { status: 'PREPARING', label: 'En Cuisine', icon: ChefHat, sound: 'notification' },
  { status: 'READY', label: 'Emballé !', icon: PackageCheck, sound: 'success' },
  { status: 'DELIVERING', label: 'Livreur en route', icon: Bike, sound: 'delivery' },
  { status: 'DELIVERED', label: 'Bon Appétit !', icon: Smile, sound: 'success' }
];

const OrderTracking: React.FC<OrderTrackingProps> = ({ order, onComplete }) => {
  const [currentStepIdx, setCurrentStepIdx] = useState(0);
  const [billoPos, setBilloPos] = useState(0);

  useEffect(() => {
    if (currentStepIdx < steps.length - 1) {
      const timer = setTimeout(() => {
        const nextIdx = currentStepIdx + 1;
        setCurrentStepIdx(nextIdx);
        playSound(steps[nextIdx].sound);
        if (steps[nextIdx].status === 'DELIVERED') onComplete();
      }, 7000); 
      return () => clearTimeout(timer);
    }
  }, [currentStepIdx]);

  useEffect(() => {
    if (steps[currentStepIdx].status === 'DELIVERING') {
      const interval = setInterval(() => {
        setBilloPos(prev => (prev < 100 ? prev + 1 : 100));
      }, 500);
      return () => clearInterval(interval);
    }
  }, [currentStepIdx]);

  return (
    <div className="space-y-6">
      <div className="bg-white p-8 rounded-[3rem] shadow-2xl border border-brand-brown/5 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-32 h-32 bg-brand-orange/5 rounded-full -mr-16 -mt-16"></div>

        <div className="flex justify-between items-center mb-8">
           <div>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 italic">Ticket Khady's</p>
              <p className="text-xl font-black italic text-brand-brown">{order.id}</p>
           </div>
           <div className="p-4 bg-brand-brown rounded-2xl text-brand-gold shadow-lg"><Navigation size={24} className="animate-pulse" /></div>
        </div>

        <div className="space-y-6">
           {steps.map((step, idx) => {
              const isCompleted = idx < currentStepIdx;
              const isCurrent = idx === currentStepIdx;
              const Icon = step.icon;

              return (
                 <div key={idx} className={`flex items-center gap-5 transition-all duration-700 ${isCurrent ? 'scale-105 opacity-100' : isCompleted ? 'opacity-40' : 'opacity-20'}`}>
                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center border-4 ${isCurrent || isCompleted ? 'bg-brand-orange text-white border-white shadow-xl' : 'bg-gray-100 text-gray-300 border-gray-50'}`}>
                       <Icon size={20} />
                    </div>
                    <div>
                       <p className="text-[8px] font-black uppercase tracking-widest text-gray-400">Étape {idx + 1}</p>
                       <p className="text-sm font-black italic text-brand-brown">{step.label}</p>
                    </div>
                 </div>
              );
           })}
        </div>
      </div>

      {steps[currentStepIdx].status === 'DELIVERING' && (
        <div className="bg-brand-brown p-8 rounded-[3rem] shadow-2xl border-4 border-white animate-fade-in">
           <div className="flex items-center justify-between mb-6">
              <h4 className="text-brand-gold font-black uppercase italic text-xs tracking-widest">Billo Express Live</h4>
              <span className="text-[8px] bg-red-500 text-white px-2 py-1 rounded-full animate-pulse font-black uppercase tracking-widest">Temps Réel</span>
           </div>

           <div className="h-2 bg-white/10 rounded-full relative overflow-hidden mb-6">
              <div className="absolute left-0 top-0 h-full bg-brand-orange shadow-[0_0_10px_rgba(255,111,0,0.8)] transition-all duration-500" style={{ width: `${billoPos}%` }}></div>
              <div className="absolute top-1/2 -translate-y-1/2 -translate-x-1/2 transition-all duration-500" style={{ left: `${billoPos}%` }}>
                 <Bike size={24} className="text-brand-gold -mt-1 shadow-lg" />
              </div>
           </div>

           <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest text-white/40">
              <span className="flex items-center gap-2 text-brand-gold"><MapPin size={12}/> Cuisine Khady</span>
              <span className="flex items-center gap-2"><MapPin size={12}/> Votre Adresse</span>
           </div>
        </div>
      )}
    </div>
  );
};

export default OrderTracking;

