import { GoogleGenAI } from "@google/genai";
import { MENU_ITEMS, BILLO_INFO } from "../constants";

export interface ChatMessage {
  role: 'user' | 'model';
  parts: { text: string }[];
}

/**
 * Khady IA - L'intelligence culinaire de Niamey
 */
export const getSmartResponse = async (userMessage: string, history: ChatMessage[] = []): Promise<string> => {
  // Use process.env.API_KEY directly as per SDK guidelines
  if (!process.env.API_KEY) {
    return "Salam ! Je prépare mes ingrédients secrets. Consultez notre menu en attendant ! 🥘 (Configuration requise)";
  }

  try {
    // Initializing SDK with apiKey from process.env.API_KEY
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const systemInstruction = `
      Tu es "Khady IA", l'ambassadrice intelligente de "Khady's Food & Event" à Niamey.

      TON : Chaleureux, poli, luxueux et typiquement nigérien.
      VOCABULAIRE : Utilise "Salam", "Barka", "Fofo", "Niamey la coquette", "C'est le goût !".

      MENU : 
      ${MENU_ITEMS.map(i => `- ${i.name} : ${i.price} F CFA`).join('\n')}

      LOGISTIQUE : 
      - Livraison par ${BILLO_INFO.name} : 1000F (centre) à 2500F (périphérie).
      - Vendredi (Jummua'h) : Pas de livraison entre 12h et 15h.

      MISSIONS :
      1. Recommande des plats selon les envies de l'utilisateur.
      2. Suggère toujours un accompagnement (Bissap, Dégué).
      3. Pour les mariages/événements, invite l'utilisateur à cliquer sur "Traiteur".
      4. Réponds en 3 phrases maximum.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [...history, { role: 'user', parts: [{ text: userMessage }] }],
      config: {
        systemInstruction,
        temperature: 0.8,
      },
    });

    // Extract text from GenerateContentResponse property directly
    return response.text || "Barka ! Je n'ai pas bien saisi, pouvez-vous reformuler ma chère ?";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Fofo ! Une petite perturbation sur la ligne, mais je reste à votre service pour vos commandes !";
  }
};

